/* ========================================
   CSS PERSONALIZADO PARA RUTAS ESPAÑA
   Pegar en: Elementor > Personalizar > CSS Adicional
   ======================================== */

/* RESET Y BASE */
* {
    box-sizing: border-box;
}

/* TIPOGRAFÍA */
body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
}

/* ========================================
   SECCIÓN HERO / HEADER
   ======================================== */
.hero-rutas {
    position: relative;
    min-height: 500px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.hero-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.3);
}

.hero-content {
    position: relative;
    z-index: 2;
    text-align: center;
    color: white;
    padding: 40px 20px;
}

.hero-content h1 {
    font-size: clamp(32px, 5vw, 48px);
    margin-bottom: 20px;
    text-shadow: 0 2px 10px rgba(0,0,0,0.3);
}

.hero-content p {
    font-size: clamp(16px, 2vw, 20px);
    margin-bottom: 40px;
    text-shadow: 0 2px 8px rgba(0,0,0,0.2);
}

/* ========================================
   BOTONES GLOBALES
   ======================================== */
.btn-primary {
    display: inline-block;
    padding: 14px 35px;
    background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
    color: white;
    text-decoration: none;
    border-radius: 8px;
    font-weight: 700;
    font-size: 16px;
    border: none;
    cursor: pointer;
    transition: all 0.3s ease;
    box-shadow: 0 4px 12px rgba(245, 158, 11, 0.3);
}

.btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 20px rgba(245, 158, 11, 0.5);
    color: white;
}

.btn-secondary {
    display: inline-block;
    padding: 12px 28px;
    background: white;
    color: #000000;
    text-decoration: none;
    border-radius: 8px;
    font-weight: 600;
    border: 2px solid #f59e0b;
    transition: all 0.3s ease;
}

.btn-secondary:hover {
    background: #f59e0b;
    color: white;
    transform: translateY(-2px);
}

/* ========================================
   CONTENEDORES Y LAYOUT
   ======================================== */
.contenedor-rutas {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 20px;
}

.seccion-rutas {
    padding: 60px 0;
}

/* ========================================
   TARJETAS Y SOMBRAS
   ======================================== */
.tarjeta {
    background: white;
    border-radius: 12px;
    box-shadow: 0 2px 15px rgba(0, 0, 0, 0.08);
    transition: all 0.3s ease;
}

.tarjeta:hover {
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.12);
    transform: translateY(-5px);
}

/* ========================================
   BADGES Y ETIQUETAS
   ======================================== */
.badge {
    display: inline-block;
    padding: 6px 14px;
    border-radius: 20px;
    font-size: 13px;
    font-weight: 600;
}

.badge-success {
    background: #d1fae5;
    color: #065f46;
}

.badge-warning {
    background: #fed7aa;
    color: #92400e;
}

.badge-danger {
    background: #fecaca;
    color: #991b1b;
}

.badge-info {
    background: #dbeafe;
    color: #1e40af;
}

/* ========================================
   ICONOS Y ELEMENTOS VISUALES
   ======================================== */
.icono-redondo {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 24px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
}

/* ========================================
   ANIMACIONES
   ======================================== */
@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.fade-in {
    animation: fadeIn 0.6s ease;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.slide-up {
    animation: slideUp 0.5s ease;
}

/* ========================================
   EFECTOS DE HOVER
   ======================================== */
.hover-lift {
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.hover-lift:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
}

.hover-scale {
    transition: transform 0.3s ease;
}

.hover-scale:hover {
    transform: scale(1.05);
}

/* ========================================
   SEPARADORES Y DIVISORES
   ======================================== */
.divisor {
    height: 1px;
    background: linear-gradient(90deg, transparent, #e5e7eb, transparent);
    margin: 40px 0;
}

.divisor-grueso {
    height: 2px;
    background: linear-gradient(90deg, transparent, #f59e0b, transparent);
    margin: 50px 0;
}

/* ========================================
   ESTADOS DE CARGA
   ======================================== */
.loading {
    display: inline-block;
    width: 40px;
    height: 40px;
    border: 4px solid #f3f4f6;
    border-top-color: #f59e0b;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* ========================================
   MENSAJES Y ALERTAS
   ======================================== */
.alerta {
    padding: 16px 20px;
    border-radius: 8px;
    margin-bottom: 20px;
    border-left: 4px solid;
}

.alerta-info {
    background: #dbeafe;
    border-color: #3b82f6;
    color: #1e40af;
}

.alerta-success {
    background: #d1fae5;
    border-color: #10b981;
    color: #065f46;
}

.alerta-warning {
    background: #fed7aa;
    border-color: #f59e0b;
    color: #92400e;
}

.alerta-danger {
    background: #fee2e2;
    border-color: #ef4444;
    color: #991b1b;
}

/* ========================================
   UTILIDADES
   ======================================== */
.text-center {
    text-align: center;
}

.text-muted {
    color: #6b7280;
}

.mb-0 { margin-bottom: 0; }
.mb-1 { margin-bottom: 8px; }
.mb-2 { margin-bottom: 16px; }
.mb-3 { margin-bottom: 24px; }
.mb-4 { margin-bottom: 32px; }
.mb-5 { margin-bottom: 40px; }

.mt-0 { margin-top: 0; }
.mt-1 { margin-top: 8px; }
.mt-2 { margin-top: 16px; }
.mt-3 { margin-top: 24px; }
.mt-4 { margin-top: 32px; }
.mt-5 { margin-top: 40px; }

/* ========================================
   RESPONSIVE
   ======================================== */
@media (max-width: 768px) {
    .seccion-rutas {
        padding: 40px 0;
    }

    .contenedor-rutas {
        padding: 0 15px;
    }

    .hero-content h1 {
        font-size: 28px;
    }

    .hero-content p {
        font-size: 16px;
    }
}

/* ========================================
   MEJORAS DE ACCESIBILIDAD
   ======================================== */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Focus visible para navegación por teclado */
*:focus-visible {
    outline: 3px solid #f59e0b;
    outline-offset: 2px;
}

/* ========================================
   SCROLLBAR PERSONALIZADO
   ======================================== */
::-webkit-scrollbar {
    width: 12px;
}

::-webkit-scrollbar-track {
    background: #f3f4f6;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #f59e0b 0%, #d97706 100%);
    border-radius: 6px;
}

::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, #d97706 0%, #b45309 100%);
}
